package com.rpb.reservation.workforce.leave.account;
import com.rpb.reservation.workforce.leave.LeaveDtos.*;import com.rpb.reservation.workforce.scheduling.SchedulingDtos.Schedule;
import com.rpb.reservation.workforce.approval.ApprovalCalculator;import com.rpb.reservation.workforce.calendar.CalendarRepository;
import com.rpb.reservation.workforce.compliance.ComplianceRepository;import com.rpb.reservation.workforce.domain.WorkforceException;
import com.rpb.reservation.walkin.api.CurrentActor;import java.math.*;import java.util.*;
import org.springframework.stereotype.Component;
/** Adapter called only inside existing leave submission/decision transaction and employee lock. */
@Component public class LeaveAccountBridge {
 private final LeaveAccountRepository repo;private final ComplianceRepository policies;private final LeaveBalanceEngine engine;private final CalendarRepository calendar;
 private final com.rpb.reservation.workforce.leave.entitlement.LeaveEntitlementService manual;
 public LeaveAccountBridge(LeaveAccountRepository repo,ComplianceRepository policies,LeaveBalanceEngine engine,CalendarRepository calendar){this(repo,policies,engine,calendar,null);}
 @org.springframework.beans.factory.annotation.Autowired public LeaveAccountBridge(LeaveAccountRepository repo,ComplianceRepository policies,LeaveBalanceEngine engine,CalendarRepository calendar,com.rpb.reservation.workforce.leave.entitlement.LeaveEntitlementService manual){this.repo=repo;this.policies=policies;this.engine=engine;this.calendar=calendar;this.manual=manual;}
 public void reserve(CurrentActor a,UUID store,Leave l,Schedule s){var c=policies.contract(a.tenantId(),l.employeeId(),s.workDate()).orElse(null);if(c==null){if(l.paid()&&manual!=null)manual.validateReservation(a.tenantId(),s.companyId(),l.employeeId(),l.typeId(),s.workDate(),l.id(),l.startAt(),l.endAt());return;}if(repo.overlaps(a.tenantId(),l.employeeId(),s.companyId(),l.id(),l.startAt(),l.endAt()))throw new WorkforceException("WORKFORCE_LEAVE_OVERLAP",409);if(!l.paid())return;if(!c.companyId().equals(s.companyId()))throw new WorkforceException("LEAVE_CONTRACT_REVIEW_REQUIRED",409);if(!repo.holds(a.tenantId(),l.id()).isEmpty())return;var binding=repo.bindings(a.tenantId(),store).stream().filter(b->b.typeId().equals(l.typeId())).findFirst().orElseThrow(()->new WorkforceException("LEAVE_TYPE_POLICY_REQUIRED",409));if(binding.kind().equals("unpaid"))throw WorkforceException.invalid();var accounts=repo.accounts(a.tenantId(),l.employeeId(),s.workDate().getYear()).stream().filter(x->x.companyId().equals(s.companyId())).toList();if(accounts.isEmpty())throw new WorkforceException("LEAVE_ACCOUNT_REQUIRED",409);if(calendar.list(a.tenantId(),store,s.workDate(),s.workDate()).stream().anyMatch(e->e.enabled()&&Set.of("public_holiday","store_rest").contains(e.kind())))throw new WorkforceException("LEAVE_NON_WORKING_DAY_REVIEW",409);var account=accounts.stream().filter(x->x.kind().equals(binding.kind())).findFirst().orElseThrow(()->new WorkforceException("LEAVE_ACCOUNT_REQUIRED",409));if(repo.reconciledOpeningDay(a.tenantId(),account,s.workDate()))throw new WorkforceException("LEAVE_OPENING_PERIOD_REVIEW_REQUIRED",409);
  var calculator=new ApprovalCalculator();var slice=new ApprovalCalculator.LeaveSlice(l.startAt(),l.endAt(),true);long net=calculator.calculate(s,null,List.of(slice),s.endAt(),false).paidLeaveSeconds();long whole=calculator.calculate(s,null,List.of(new ApprovalCalculator.LeaveSlice(s.startAt(),s.endAt(),true)),s.endAt(),false).paidLeaveSeconds();if(net<=0||whole<=0)throw WorkforceException.invalid();var units=account.unit().equals("hour")?BigDecimal.valueOf(net).divide(BigDecimal.valueOf(3600),6,RoundingMode.HALF_UP):BigDecimal.valueOf(net).divide(BigDecimal.valueOf(whole),6,RoundingMode.HALF_UP);engine.reserve(a,account,l.id(),"leave",s.workDate(),units);if(binding.kind().equals("sick")){var shared=accounts.stream().filter(x->x.kind().equals("hospital")&&x.unit().equals(account.unit())).findFirst().orElseThrow(()->new WorkforceException("LEAVE_ACCOUNT_REQUIRED",409));engine.reserve(a,shared,l.id(),"leave",s.workDate(),units);}
 }
 public void decision(CurrentActor a,UUID store,Leave l,Schedule s,String action){if(!l.paid())return;if(action.equals("approved")){var binding=repo.bindings(a.tenantId(),store).stream().filter(b->b.typeId().equals(l.typeId())).findFirst().orElse(null);if(binding!=null&&policies.contract(a.tenantId(),l.employeeId(),s.workDate()).isPresent()&&Set.of("sick","hospital").contains(binding.kind())&&(l.medicalReference()==null||l.medicalReference().isBlank()))throw new WorkforceException("LEAVE_MEDICAL_EVIDENCE_REQUIRED",409);if(repo.holds(a.tenantId(),l.id()).isEmpty())reserve(a,store,l,s);engine.transition(a,l.id(),"used","Leave approved");}else if(Set.of("rejected","withdrawn","cancelled").contains(action))engine.transition(a,l.id(),"released","Leave "+action);}
}
